def solve(grid):
    rows = len(grid)
    cols = len(grid[0])
    # Find columns with 5s and their count
    col_counts = {}
    for c in range(cols):
        count = sum(1 for r in range(rows) if grid[r][c] == 5)
        if count > 0:
            col_counts[c] = count
    # Sort by count descending
    sorted_cols = sorted(col_counts.keys(), key=lambda c: -col_counts[c])
    result = [row[:] for row in grid]
    for i, c in enumerate(sorted_cols):
        for r in range(rows):
            if result[r][c] == 5:
                result[r][c] = i + 1
    return result
